window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-51d68d35e95f951a"]={"versions": [{"id": "FIG-51d68d35e95f951a", "releases": ["R1.5.1", "R18-10_R4.4.0_R1.5.0", "R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation eines Teilschritts der AUTOSAR-E2E-Protokollbibliothek (<code>AUTOSAR_PRS_E2EProtocol</code>). Das Diagramm beschreibt den sequenziellen Einzelschritt „Write Counter“ innerhalb der Schutzfunktion <code>E2E_P04Protect()</code> für das E2E-Profil 4.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Kontextsymbol / Aktivitätsbezeichner oben links: <code>E2E_P04Protect()</code>\n</li><li>Startknoten (Initial Node)\n</li><li>Aktionsknoten (Action): <code>Copy 2-byte State-&gt;Counter on bytes Data[Offset+2...Offset+3] in Big Endian order</code>\n</li><li>Endknoten (Activity Final Node)\n</li><li>Relevante Daten- und Zustandselemente: Zustandsstruktur <code>State</code> mit Feld <code>Counter</code> (2 Byte), Datenpuffer <code>Data[]</code> mit Adressierung über Basis-<code>Offset</code> (Bytes <code>Offset+2</code> und <code>Offset+3</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Beginn der Ausführung am Startknoten nach Aufruf bzw. Erreichen der Sequenzphase in <code>E2E_P04Protect()</code>.\n</li><li>Ausführung des Aktionsschritts: Der 2 Byte breite Zählerwert aus <code>State-&gt;Counter</code> wird in Big-Endian-Byte-Reihenfolge in das Byte-Array <code>Data</code> an die Positionen <code>Offset + 2</code> bis <code>Offset + 3</code> geschrieben.\n</li><li>Ablaufübergang auf den Aktivitaets-Endknoten zum Abschluss dieses Einzelschritts.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Darstellung ist über Anforderung <code>[PRS_E2E_00365]</code> normativ verbindlich. Bei der Implementierung von E2E Profile 4 Protect ist zwingend darauf zu achten, dass das Feld <code>Counter</code> genau 2 Bytes belegt und unabhängig von der nativen Host-Endianness im Big-Endian-Format (Most Significant Byte zuerst auf <code>Data[Offset+2]</code>, Least Significant Byte auf <code>Data[Offset+3]</code>) in den Nutzdatenpuffer serialisiert wird.</p>"}, {"id": "FIG-91ce4a481e5b0832", "releases": ["R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation eines Teilschritts der AUTOSAR-E2E-Protokollbibliothek (<code>AUTOSAR_PRS_E2EProtocol</code>). Das Diagramm beschreibt den sequenziellen Einzelschritt „Write Counter“ innerhalb der Schutzfunktion <code>E2E_P04Protect()</code> für das E2E-Profil 4.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Kontextsymbol / Aktivitätsbezeichner oben links: <code>E2E_P04Protect()</code>\n</li><li>Startknoten (Initial Node)\n</li><li>Aktionsknoten (Action): <code>Copy 2-byte State-&gt;Counter on bytes Data[Offset+2...Offset+3] in Big Endian order</code>\n</li><li>Endknoten (Activity Final Node)\n</li><li>Relevante Daten- und Zustandselemente: Zustandsstruktur <code>State</code> mit Feld <code>Counter</code> (2 Byte), Datenpuffer <code>Data[]</code> mit Adressierung über Basis-<code>Offset</code> (Bytes <code>Offset+2</code> und <code>Offset+3</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Beginn der Ausführung am Startknoten nach Aufruf bzw. Erreichen der Sequenzphase in <code>E2E_P04Protect()</code>.\n</li><li>Ausführung des Aktionsschritts: Der 2 Byte breite Zählerwert aus <code>State-&gt;Counter</code> wird in Big-Endian-Byte-Reihenfolge in das Byte-Array <code>Data</code> an die Positionen <code>Offset + 2</code> bis <code>Offset + 3</code> geschrieben.\n</li><li>Ablaufübergang auf den Aktivitaets-Endknoten zum Abschluss dieses Einzelschritts.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Darstellung ist über Anforderung <code>[PRS_E2E_00365]</code> normativ verbindlich. Bei der Implementierung von E2E Profile 4 Protect ist zwingend darauf zu achten, dass das Feld <code>Counter</code> genau 2 Bytes belegt und unabhängig von der nativen Host-Endianness im Big-Endian-Format (Most Significant Byte zuerst auf <code>Data[Offset+2]</code>, Least Significant Byte auf <code>Data[Offset+3]</code>) in den Nutzdatenpuffer serialisiert wird.</p>"}], "trans": [{"from": "FIG-51d68d35e95f951a", "to": "FIG-91ce4a481e5b0832", "fr": "R19-03", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
